Param([switch]$Headless)  # --- Ensure full user PATH is available (subprocess contexts may start bare) --- $env:PATH = [System.Environment]::GetEnvironmentVariable("PATH","Machine") + ";" +             [System.Environment]::GetEnvironmentVariable("PATH","User") # -------------------------------------------------------------------------------  # --- SOTA Headless Standard --- if ($Headless -and ($Host.UI.RawUI.WindowTitle -notmatch "Hidden")) {     Start-Process powershell.exe -ArgumentList "-NoProfile","-File",$PSCommandPath,"-Headless" -WindowStyle Hidden     exit } $WindowStyle = if ($Headless) { "Hidden" } else { "Normal" } # ------------------------------  $BackendPort  = 10964 $FrontendPort = 10965 $ApiHealth    = "http://127.0.0.1:$BackendPort/api/health" $RepoRoot     = Split-Path -Parent $PSScriptRoot $WebRoot      = $PSScriptRoot  # =========================================================================== # Prereq check -- installs uv and Node via winget if absent. # =========================================================================== function Require-Command {     param([string]$Cmd, [string]$WingetId, [string]$Label)     if (Get-Command $Cmd -ErrorAction SilentlyContinue) { return }     Write-Host "  $Label not found - installing via winget ..." -ForegroundColor Yellow     if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {         Write-Host "ERROR: winget unavailable. Install $Label manually ($WingetId)." -ForegroundColor Red         exit 1     }     winget install --id $WingetId --silent --accept-source-agreements --accept-package-agreements     $env:PATH = [System.Environment]::GetEnvironmentVariable("PATH","Machine") + ";" +                 [System.Environment]::GetEnvironmentVariable("PATH","User")     if (-not (Get-Command $Cmd -ErrorAction SilentlyContinue)) {         Write-Host "Installed $Label but '$Cmd' still not in PATH. Reopen PowerShell and retry." -ForegroundColor Yellow         exit 1     } }  # Ensure known Node.js install dir is on PATH if node isn't already visible if (-not (Get-Command node -ErrorAction SilentlyContinue)) {     $nodeDir = "C:\Program Files\nodejs"     if (Test-Path "$nodeDir\node.exe") {         $env:PATH = "$nodeDir;" + $env:PATH     } else {         Write-Host "ERROR: node not found. Install Node.js LTS from https://nodejs.org/" -ForegroundColor Red         exit 1     } }  # Resolve uv: prefer known install path, fall back to PATH $uvExe = "C:\Users\sandr\.local\bin\uv.exe" if (-not (Test-Path $uvExe)) {     $uvCmd = Get-Command uv -ErrorAction SilentlyContinue; $uvExe = if ($uvCmd) { $uvCmd.Source } else { $null }     if (-not $uvExe) {         Write-Host "ERROR: uv not found. Install from https://docs.astral.sh/uv/" -ForegroundColor Red         exit 1     } } $npmCmd = Get-Command npm -ErrorAction SilentlyContinue if (-not $npmCmd) { Write-Host "ERROR: npm not found after PATH setup." -ForegroundColor Red; exit 1 } # Prefer npm.cmd over npm.ps1 for reliable invocation $npmExe = if ($npmCmd.Source -match '\.ps1$') {     $npmCmd.Source -replace '\.ps1$', '.cmd' } else { $npmCmd.Source }  # Python deps $LASTEXITCODE = 0 Write-Host "Syncing Python deps (uv sync) ..." -ForegroundColor Cyan Write-Host "(first run: uv may download Python 3.11 -- this can take 30s)" -ForegroundColor DarkGray & $uvExe sync --project $RepoRoot --extra dev if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: uv sync failed." -ForegroundColor Red; exit 1 }  # Frontend deps (npm install only if node_modules absent) if (-not (Test-Path (Join-Path $WebRoot "node_modules"))) {     Write-Host "Installing frontend deps (npm install) ..." -ForegroundColor Cyan     Push-Location $WebRoot     & $npmExe install --prefer-offline 2>&1     if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: npm install failed." -ForegroundColor Red; Pop-Location; exit 1 }     Pop-Location }  # Guard: vite must exist locally after install $viteLocal = Join-Path $WebRoot "node_modules\.bin\vite" if (-not (Test-Path $viteLocal)) {     Write-Host "ERROR: vite missing from node_modules after npm install." -ForegroundColor Red     Write-Host "Delete '$WebRoot\node_modules' and re-run." -ForegroundColor Yellow     exit 1 }  # Clear ports foreach ($port in @($BackendPort, $FrontendPort)) {     $procIds = Get-PortListenerPidsFast -Port $port
